package com.acme.orders.entity; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="purchase_orders") public class PurchaseOrder {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false)private String customerEmail;@Column(nullable=false)private String sku;@Column(nullable=false)private int quantity;@Column(nullable=false,precision=12,scale=2)private BigDecimal unitPrice;@Column(nullable=false)private Instant createdAt;@PrePersist void create(){createdAt=Instant.now();}public PurchaseOrder(){}public PurchaseOrder(String e,String s,int q,BigDecimal p){customerEmail=e;sku=s;quantity=q;unitPrice=p;}public Long getId(){return id;}public String getCustomerEmail(){return customerEmail;}public String getSku(){return sku;}public int getQuantity(){return quantity;}public BigDecimal getUnitPrice(){return unitPrice;}public Instant getCreatedAt(){return createdAt;}}
